import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Max Pooling 2D
maxpool2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void maxpool2d_kernel(const float* input, float* output, int batch_size, int channels, int height, int width, int pooled_height, int pooled_width, int kernel_size, int stride, int padding, int dilation) {
    int n = blockIdx.x;
    int c = blockIdx.y;
    int ph = blockIdx.z / pooled_width;
    int pw = blockIdx.z % pooled_width;

    int h_start = ph * stride - padding;
    int w_start = pw * stride - padding;
    int h_end = min(h_start + (kernel_size - 1) * dilation + 1, height);
    int w_end = min(w_start + (kernel_size - 1) * dilation + 1, width);

    float max_val = -FLT_MAX;
    for (int h = h_start; h < h_end; h += dilation) {
        for (int w = w_start; w < w_end; w += dilation) {
            if (h >= 0 && w >= 0 && h < height && w < width) {
                int idx = n * channels * height * width + c * height * width + h * width + w;
                max_val = max(max_val, input[idx]);
            }
        }
    }
    int out_idx = n * channels * pooled_height * pooled_width + c * pooled_height * pooled_width + ph * pooled_width + pw;
    output[out_idx] = max_val;
}

torch::Tensor maxpool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    int pooled_height = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int pooled_width = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, channels, pooled_height, pooled_width}, input.options());

    dim3 blocks(batch_size, channels, pooled_height * pooled_width);
    maxpool2d_kernel<<<blocks, 1>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, height, width, pooled_height, pooled_width, kernel_size, stride, padding, dilation);

    return output;
}
"""

maxpool2d_cpp_source = (
    "torch::Tensor maxpool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation);"
)

# Compile the inline CUDA code for Max Pooling 2D
maxpool2d = load_inline(
    name="maxpool2d",
    cpp_sources=maxpool2d_cpp_source,
    cuda_sources=maxpool2d_source,
    functions=["maxpool2d_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.maxpool2d = maxpool2d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.maxpool2d.maxpool2d_cuda(x, self.kernel_size, self.stride, self.padding, self.dilation)
